/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.toDate(); // 오늘날짜 설정

        const sbmOptions = {
            id : "sbm_MxDataSet_List1",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_List1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_MxDataSet_List2",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_List2=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions3 = {
            id : "sbm_MxDataSet_List3",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_List3=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_MxDataSet_List4",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "MxDataSet_List4=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.cm.PanelToGroupBox_01(panel_1);
        $c.cm.PanelToGroupBox_01(panel_2);
        $c.cm.PanelToGroupBox_01(panel_3);
        scwin.listAll();
        scwin.listListing();
        await scwin.setCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34100.onpageload" });
    }
};

