/**
 * @method
 * @name MxTab_OnSelChanged
 * @description Mx Tab On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_OnSelChanged = function(nIndex) {
    try {
        if (nIndex === 1) {
            // 탭인덱스 1  : 직접공시제 지정기업 현황
            scwin.listAll();
        } else if (nIndex === 2) {
            // 탭인덱스 2 : 직접공시제 기업 지정
            scwin.listListing();
        } else if (nIndex === 3) {
            // 탭인덱스 3 : 직접공시제 요건 확인
            scwin.srhTab3();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34100.MxTab_OnSelChanged" });
    }
};

/**
 * @method
 * @name MxDataSet_List1_OnFilter
 * @description Mx Data Set List1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_List1_OnFilter = function(row) {
    try {
        lst_gubun = rdo_gubun.getValue();
        f3 = MxDataSet_List1.getCellData(row, "LIST_STAT_CD");
        if (scwin.skw !== "") {
            f1 = MxDataSet_List1.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_List1.getCellData(row, "OLD_COM_ABBRV");
            if (lst_gubun === 0) {
                if (f1.indexOf(scwin.skw) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else if (f2.indexOf(scwin.skw) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else {
                    return false;
                }
            } else {
                if (f1.indexOf(scwin.skw) !== -1 && f3.indexOf(lst_gubun) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else if (f2.indexOf(scwin.skw) !== -1 && f3.indexOf(lst_gubun) !== -1) {
                    scwin.filter_cnt++;
                    return true;
                } else {
                    return false;
                }
            }
        } else {
            if (lst_gubun === 0) {
                scwin.filter_cnt++;
                return true;
            } else if (f3.indexOf(lst_gubun) !== -1) {
                scwin.filter_cnt++;
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34100.MxDataSet_List1_OnFilter" });
    }
};

