/**
 * @method
 * @name grd_List3_oncheckclick
 * @description grd_List3 oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List3_oncheckclick = async function(col, colid, bCheck) {
    try {
        if (MxDataSet_List3.getCellData(col, "CHK_FLAG") === 1) {
            // 현재 종목의 지정 여부 체크
            if (await scwin.getDircDisclsSysCheck(col, MxDataSet_List3, MxDataSet_List3.getCellData(col, "ISUR_CD"), "check", "")) {
                // 선택된 종목 체크
                for (let i = 1; i <= MxDataSet_List4.getRowCount(); i++) {
                    if (MxDataSet_List4.getCellData(i, "ISUR_CD") === MxDataSet_List3.getCellData(col, "ISUR_CD")) {
                        await $c.win.alert("이미 선택된 종목입니다.");
                        scwin.chkCancle(MxDataSet_List3);
                        return false;
                    }
                }
            } else {
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34100.grd_List3_oncheckclick" });
    }
};

/**
 * @method
 * @name grd_List3_onheadcheckclick
 * @description grd_List3 onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List3_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let gcnt = MxDataSet_List3.getRowCount();
        if (gcnt > 0) {
            grd_List3.Redraw = false;
            for (let i = 1; i <= gcnt; i++) {
                MxDataSet_List3.setCellData(i, "CHK_FLAG", bCheck);
            }
            grd_List3.Redraw = true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34100.grd_List3_onheadcheckclick" });
    }
};

