/**
 * @method
 * @name toDate
 * @description to Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.toDate = function() {
    const clientnow = new Date();
    /* 오늘 날짜를 구한다 */
    const curYear = clientnow.getYear();
    let curMonth = (clientnow.getMonth()) + 1;
    let curDay = clientnow.getDate();
    if (curMonth <= 9) {
        curMonth = "0" + curMonth;
    }
    if (curDay <= 9) {
        curDay = "0" + curDay;
    }
    movingtime = curYear + "" + curMonth + "" + curDay;
    scwin.todat = movingtime;
    edt_strt_dd.setValue(scwin.todat); // 탭2

};

