/**
 * @method
 * @name cntDatasetRowCheck
 * @description ---------------------------------------------------------------------------- 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. -------------------------------------------------------------------------------
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.cntDatasetRowCheck = function(sval) {
    cCnt = 0;
    for (i = 1; i <= sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name chkCancle
 * @description 데이터셋 체크박스 초기화
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.chkCancle = function(sval) {
    // 데이터셋 체크박스 초기화
    for (let i = 1; i <= sval.getRowCount(); i++) {
        sval.setCellData(i, "CHK_FLAG", 0);
    }
};

/**
 * @method
 * @name undo
 * @description undo 처리
 * @param {*} sval sval
 * @returns {void}
 * @hidden N
 */
scwin.undo = function(sval) {
    sval.undoall();
};

