    } else {
        MxDataSet_List1.UseFilter = "true";
        MxDataSet_List1.Filter();
        MxDataSet_List1.setRowPosition(1, 0);
    }
};

/**
 * @method
 * @name confirm
 * @description 선택
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    let total = 0;
    let dircDisclsSysYnNm;
    let dircDisclsSysYn;
    for (let i = 1; i <= MxDataSet_List3.getRowCount(); i++) {
        let chk = MxDataSet_List3.getCellData(i, "CHK_FLAG");
        if (chk === "T" || chk === 1) total++;
    }
    if (cmb_select.getValue() === "S") {
        await $c.win.alert("직접공시제 지정·해제를 선택하세요.");
        cmb_select.focus();
        return false;
    } else if (cmb_select.getValue() === "Y") {
        dircDisclsSysYnNm = "지정";
        dircDisclsSysYn = "Y";
    } else if (cmb_select.getValue() === "N") {
        dircDisclsSysYnNm = "해제";
        dircDisclsSysYn = "N";
    } else {
        return false;
    }
    if (total === 0) {
        await $c.win.alert("종목을 선택하세요.");
        return false;
    }
    let vStrt_dd = edt_strt_dd.getValue();
    MxDataSet_List4.setBroadcast(false);
    let j = 1 + MxDataSet_List4.getRowCount();
    for (let i = 1; i <= MxDataSet_List3.getRowCount(); i++) {
        let chk = MxDataSet_List3.getCellData(i, "CHK_FLAG");
        if (chk === "T" || chk === 1) {
            if (await scwin.getDircDisclsSysCheck(i, MxDataSet_List3, MxDataSet_List3.getCellData(i, "ISUR_CD"), "check", "")) {
                MxDataSet_List4.insertRow();
                MxDataSet_List4.setCellData(j, "CHK_FLAG", "T");
                MxDataSet_List4.setCellData(j, "CHK_FLAG", 1);
                MxDataSet_List4.setCellData(j, "ISUR_CD", MxDataSet_List3.getCellData(i, "ISUR_CD"));
                MxDataSet_List4.setCellData(j, "COM_ABBRV", MxDataSet_List3.getCellData(i, "COM_ABBRV"));
                MxDataSet_List4.setCellData(j, "DESIGN_ADVSER_COM_ABBRV", MxDataSet_List3.getCellData(i, "DESIGN_ADVSER_COM_ABBRV"));
                MxDataSet_List4.setCellData(j, "DIRC_DISCLS_SYS_YN_NM", dircDisclsSysYnNm);
                MxDataSet_List4.setCellData(j, "DIRC_DISCLS_SYS_YN", dircDisclsSysYn);
                MxDataSet_List4.setCellData(j, "REG_ID", scwin.gEmpNo);
                MxDataSet_List4.setCellData(j, "DESIGN_DD", vStrt_dd);
                j++;
            } else {
                // resetMxDataSet_List4();
                return false;
            }
        }
    }
    MxDataSet_List4.setBroadcast(true);
    scwin.chkCancle(MxDataSet_List3);
    return true;
};

/**
 * @method
 * @name getDircDisclsSysCheck
 * @description 직접공시제 체크
 * @param {*} num num
 * @param {Object} obj 컴포넌트
 * @param {*} val val
 * @param {*} gbn gbn
 * @param {*} yn yn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDircDisclsSysCheck = async function(num, obj, val, gbn, yn) {
    let vDIRC_DISCLS_SYS_YN;
    let vDIRC_DISCLS_SYS_DD;
    let vDIRC_DISCLS_SYS_YN_NM;
    let url_list = "/ListedCompany.do?method=getDircDisclsSysCheck&inputMessageId=DIRC_DISCLS_SYS_LIST_INOUT" + "&outputMessageId=DIRC_DISCLS_SYS_LIST_INOUT";
    let url_cond = "&ISUR_CD=" + val + "&SCREN_ID=" + 'ULDSTF34100.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_check.DataID = encodeURI(url_list + url_cond);
    dts_check.reset();
    vDIRC_DISCLS_SYS_YN = dts_check.getCellData(1, "DIRC_DISCLS_SYS_YN");
    vDIRC_DISCLS_SYS_DD = dts_check.getCellData(1, "DIRC_DISCLS_SYS_DD");
    if (vDIRC_DISCLS_SYS_YN === "Y") {
        vDIRC_DISCLS_SYS_YN_NM = "지정";
    } else if (vDIRC_DISCLS_SYS_YN === "N") {
        vDIRC_DISCLS_SYS_YN_NM = "해제";
    } else {

    }
    let vStrt_dd = edt_strt_dd.getValue();
    if (vStrt_dd === '') {
        await $c.win.alert("지정·해제일자를 선택하세요");
        edt_strt_dd.focus();
        return;
    }
    if (vStrt_dd < $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("지정·해제일자를 오늘 날짜 이후로 지정하세요");
        edt_strt_dd.focus();
        return;
    }
    if (obj.getCellData(num, "CHK_FLAG") === 1) {
        if (vDIRC_DISCLS_SYS_DD >= vStrt_dd) {
            await $c.win.alert("'" + obj.getCellData(num, "COM_ABBRV") + "' 의 " + vDIRC_DISCLS_SYS_YN_NM + " 일자 이후로 지정해주세요");
            scwin.chkCancle(obj);
            scwin.listListing();
            return false;
        }
    }

    // for (var i = 1;i <=obj.CountRow ;i++) {
    /*	if(obj.NameValue(num, "CHK_FLAG") == 1) {
    		if(vDIRC_DISCLS_SYS_DD == todat){
    			alert("'"+obj.NameValue(num,"COM_ABBRV") + "' 는(은) 오늘 이미 " + vDIRC_DISCLS_SYS_YN_NM + " 되었습니다.");
    			fn_chk_cancle(obj);
    			fn_list_listing();
    			return false;
    		}
    	}*/
    // }

    if (gbn === "check") {
        // 선택일때
        if (cmb_select.getValue() === 'S') {
            await $c.win.alert("직접공시제 지정·해제를 선택하세요.");
            scwin.chkCancle(MxDataSet_List3);
            cmb_select.focus();
            return false;
            // 지정일때
        } else if (cmb_select.getValue() === 'Y') {
            if (vDIRC_DISCLS_SYS_YN === "Y") {
                await $c.win.alert("이미 지정된 상태입니다.");
                scwin.chkCancle(MxDataSet_List3);
                return false;
            } else {
                return true;
            }
            // 해제일때

        } else if (cmb_select.getValue() === 'N') {
            // 데이터가 없으면 통과
            if (vDIRC_DISCLS_SYS_YN === undefined) {
                await $c.win.alert("미지정 상태로 해제할 수 없습니다.");
                scwin.chkCancle(MxDataSet_List3);
                return false;
            } else if (vDIRC_DISCLS_SYS_YN === "N") {
                await $c.win.alert("이미 해제된 상태입니다.");
                scwin.chkCancle(MxDataSet_List3);
                return false;
            } else {
                return true;
            }
        } else {
            return true;
        }
    } else {
        if (yn === "Y") {
            if (vDIRC_DISCLS_SYS_YN === "Y") {
                await $c.win.alert("이미 지정된 상태입니다.");
                return false;
            }
            return true;
        } else if (yn === "N") {
            if (vDIRC_DISCLS_SYS_YN === "N") {
                await $c.win.alert("이미 해제된 상태입니다.");
                return false;
            }
            return true;
        } else {
            return true;
        }
